import { useState } from "react";

const LOGO_B64 = "";

const C = {
  navy: "#0B1E3F", gold: "#B8871E", red: "#c0392b",
  white: "#ffffff", offwhite: "#FAFBFC", muted: "#6E6E73",
  border: "#E8E8ED", light: "#F5F5F7", text: "#1D1D1F",
};
const font = "-apple-system, BlinkMacSystemFont, Inter, Space Grotesk, sans-serif";

const btnSolid = (bg, color) => ({
  width: "100%", padding: "15px", background: bg, color,
  border: "none", borderRadius: 12, fontSize: 16, fontFamily: font,
  fontWeight: 600, cursor: "pointer", letterSpacing: "-0.01em",
  transition: "opacity 0.2s",
});
const btnOutline = (color, border) => ({
  width: "100%", padding: "15px", background: "transparent", color,
  border: `1.5px solid ${border}`, borderRadius: 12, fontSize: 16,
  fontFamily: font, fontWeight: 600, cursor: "pointer",
  letterSpacing: "-0.01em", transition: "opacity 0.2s",
});

export default function SinclairLogin() {
  const [mode, setMode] = useState(null);
  const [email, setEmail] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");

  function handleSubmit(e) {
    e.preventDefault();
    setError("");
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError("Please enter a valid email address.");
      return;
    }
    setSubmitted(true);
  }

  function reset() { setMode(null); setEmail(""); setSubmitted(false); setError(""); }

  const card = {
    background: C.white, borderRadius: 20, padding: "36px 32px",
    boxShadow: "0 2px 24px rgba(0,0,0,0.07)", border: `1px solid ${C.border}`,
  };

  return (
    <div style={{ minHeight: "100vh", background: C.offwhite, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "space-between", fontFamily: font }}>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", width: "100%", padding: "60px 24px" }}>
        <div style={{ width: "100%", maxWidth: 400 }}>

          {/* Logo — centered, transparent */}
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 52 }}>
            <img src={`data:image/png;base64,${LOGO_B64}`} alt="Sinclair"
              style={{ width: 220, height: "auto" }} />
          </div>

          {mode === null && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <button onClick={() => window.location.href = "/employer"} style={{...btnSolid(C.navy, C.white)}}>Employer Login</button>
              <button onClick={() => setMode("employee")} style={{...btnOutline(C.navy, C.border)}}>Employee Login</button>
              <div style={{ textAlign: "center", marginTop: 20 }}>
                <button onClick={() => setMode("demo")} style={{ background: "none", border: "none", color: C.muted, fontSize: 14, cursor: "pointer", fontFamily: font }}>
                  Explore without logging in
                </button>
              </div>
            </div>
          )}

          {mode === "employee" && !submitted && (
            <div style={{...card}}>
              <h2 style={{ fontSize: 22, color: C.text, fontWeight: 600, marginTop: 0, marginBottom: 6, letterSpacing: "-0.02em" }}>Employee Login</h2>
              <p style={{ fontSize: 14, color: C.muted, marginBottom: 28, marginTop: 0 }}>Enter your email to receive a secure login link.</p>
              <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="your@email.com"
                  style={{ width: "100%", padding: "14px 16px", fontSize: 15, border: `1.5px solid ${C.border}`, borderRadius: 10, outline: "none", fontFamily: font, boxSizing: "border-box", color: C.text, background: C.offwhite }} />
                {error && <p style={{ color: C.red, fontSize: 13, margin: 0 }}>{error}</p>}
                <button type="submit" style={{...btnSolid(C.navy, C.white)}}>Send Login Link</button>
              </form>
              <div style={{ marginTop: 20, textAlign: "center" }}>
                <button onClick={reset} style={{ background: "none", border: "none", color: C.muted, fontSize: 13, cursor: "pointer", fontFamily: font }}>Back</button>
              </div>
            </div>
          )}

          {mode === "employee" && submitted && (
            <div style={{...card, textAlign: "center", padding: "48px 32px"}}>
              <div style={{ fontSize: 40, marginBottom: 16 }}>✓</div>
              <h3 style={{ color: C.text, fontSize: 20, fontWeight: 600, marginBottom: 8, marginTop: 0 }}>Check your inbox</h3>
              <p style={{ fontSize: 14, color: C.muted, marginBottom: 24 }}>A secure link has been sent to <strong>{email}</strong>.</p>
              <button onClick={reset} style={{ background: "none", border: "none", color: C.navy, fontSize: 14, cursor: "pointer", fontFamily: font, fontWeight: 600 }}>Use a different email</button>
            </div>
          )}

          {mode === "demo" && (
            <div style={{...card, textAlign: "center"}}>
              <div style={{ background: C.offwhite, borderRadius: 10, padding: "10px 16px", marginBottom: 24, fontSize: 13, color: C.muted }}>Demo Mode - Data is not saved</div>
              <p style={{ fontSize: 15, color: C.text, marginBottom: 28, lineHeight: 1.7 }}>Browse all tools as a guest. Create an account when you're ready to save your progress.</p>
              <button onClick={() => window.location.href = "/demo"} style={{...btnSolid(C.navy, C.white)}}>Enter Demo</button>
              <div style={{ marginTop: 16 }}>
                <button onClick={reset} style={{ background: "none", border: "none", color: C.muted, fontSize: 13, cursor: "pointer", fontFamily: font }}>Back</button>
              </div>
            </div>
          )}
        </div>
      </div>
      <footer style={{ padding: "24px", textAlign: "center", color: C.muted, fontSize: 12, letterSpacing: "0.02em" }}>
        © Sinclair LLC 2026
      </footer>
    </div>
  );
}
